<script lang="ts">
 import {onMount,untrack} from 'svelte';
 import {api} from './api';
 import {latestRequest} from './latest-request';
 import {localDateWindow} from './time-audience';
 import {publicationGroups,stepPath,subscriberSteps} from './subscriber-chart';
 import type {StreamStore} from '../../../packages/core/src/store';
 import type {Publication} from '../../../packages/core/src/subscriber-history';
 import Help from './Help.svelte';
 let {profile,timezone='Europe/Moscow',onStream}:{profile:string;timezone?:string;onStream:(id:string)=>void}=$props();
 type Report=ReturnType<StreamStore['subscriberHistory']>;
 const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 let source=$state<'twitch'|'youtube'>('twitch'),days=$state(1),day=$state(untrack(today)),ready=$state(false),width=$state(700),loading=$state(false),error=$state('');
 let data=$state<Report|null>(null),selection=$state<Publication|null>(null),selectedGroup=$state<string[]>([]),selectedPoint=$state<number|null>(null),publicationsOpen=$state(false);
 let selectedStream=$state<Report['streams'][number]|null>(null);
 const request=latestRequest();
 const window=$derived.by(()=>{const end=localDateWindow(day,timezone).to;return {from:localDateWindow(new Date(Date.parse(day)-86400000*(days-1)).toISOString().slice(0,10),timezone).from,to:end};});
 const color=$derived(source==='twitch'?'var(--twitch,#a970ff)':'var(--youtube,#ff5959)');
 const plotWidth=$derived(Math.max(280,width)),left=42,right=18;
 const x=(at:number)=>left+(Math.max(window.from,Math.min(window.to,at))-window.from)/(window.to-window.from)*(plotWidth-left-right);
 const points=$derived(subscriberSteps(data?.counts??[],data?.follows??[],source,window.from));
 const currentPoint=$derived(points.find(point=>point.at===selectedPoint));
 const low=$derived(Math.min(...points.map(p=>p.total),data?.total??0)),high=$derived(Math.max(...points.map(p=>p.total),low+2));
 const y=(value:number)=>230-(value-low)/Math.max(2,high-low)*200;
 const groups=$derived(publicationGroups(data?.publications??[],window.from,window.to,plotWidth-left-right));
 const label=(at:number,date=false)=>new Intl.DateTimeFormat('ru-RU',{timeZone:timezone,...(date?{day:'2-digit',month:'2-digit'}:{hour:'2-digit',minute:'2-digit'})}).format(at);
 const dateRange=$derived(days===1?label(window.from,true):`${label(window.from,true)}–${label(window.to-1,true)}`);
 const kind=(item:Publication)=>item.kind==='shorts'?'Shorts':item.kind==='video'?'Видео':'Тип уточняется';
 const shift=(direction:number)=>{day=new Date(Date.parse(day)+direction*days*86400000).toISOString().slice(0,10);};
 async function load(){
  loading=true;error='';const scope=JSON.stringify([profile,source,days,day,timezone]);
  const to=Math.min(window.to,Date.now());
  if(to<=window.from){data=null;loading=false;return;}
  await request.run(signal=>api<Report>(`analytics/subscribers?${new URLSearchParams({source,from:String(window.from),to:String(to)})}`,undefined,signal),result=>{if(scope!==JSON.stringify([profile,source,days,day,timezone]))return;data=result;loading=false;},e=>{error=e.message;loading=false;});
 }
 $effect(()=>{void profile;void source;void days;void day;void timezone;if(!ready)return;untrack(()=>{data=null;selection=null;selectedStream=null;selectedPoint=null;selectedGroup=[];void load();});});
 onMount(()=>{ready=true;const refresh=()=>void load();globalThis.window.addEventListener('sp:data-refresh',refresh);return()=>{request.cancel();globalThis.window.removeEventListener('sp:data-refresh',refresh);};});
 const selectGroup=(items:Publication[])=>{selectedGroup=items.map(i=>i.id);publicationsOpen=true;selection=items[0]??null;};
</script>
<section class="panel subscriber-growth" style:--subscriber-color={color} aria-busy={loading}>
 <header><div class="subscriber-heading"><h2>Подписчики</h2><Help id="subscriber-growth" label="О графике подписчиков" text={`Отдельная история текущего канала, включая время вне эфиров. У графика собственный период; категория его не ограничивает. Twitch сообщает точное время фоллоу. Рост ставится в это время, когда он совпадает с изменением счётчика; отписки выявляются при сверке. YouTube показывает общий счётчик по замерам, а не время каждой подписки; с 1000 подписчиков он округляется. При короткой истории изменение за весь период неизвестно. Тип новой публикации уточняется после обработки YouTube Analytics. Запись эфира не дублируется точкой видео.${data?.lastAt!=null?` Последний замер: ${label(data.lastAt,true)} ${label(data.lastAt)}.`:''}`}/></div><div class="subscriber-switch platform-switch" role="group" aria-label="Площадка подписчиков">{#each ['twitch','youtube'] as platform}<button class:active={source===platform} aria-pressed={source===platform} onclick={()=>source=platform as typeof source}>{platform==='twitch'?'Twitch':'YouTube'}</button>{/each}</div></header>
 <div class="subscriber-controls"><div class="subscriber-switch period-switch" role="group" aria-label="Период подписчиков">{#each [1,7,30] as n}<button class:active={days===n} aria-pressed={days===n} onclick={()=>days=n}>{n===1?'Сутки':`${n} дней`}</button>{/each}</div>
 <div class="subscriber-date"><button class="outline" aria-label="Предыдущий период подписчиков" onclick={()=>shift(-1)}>‹</button><label><span aria-hidden="true">{dateRange}</span><input aria-label="Дата подписчиков" type="date" value={day} onchange={e=>{if(e.currentTarget.validity.valid&&e.currentTarget.value)day=e.currentTarget.value;else e.currentTarget.value=day;}} max={today()} required/></label><button class="outline" aria-label="Следующий период подписчиков" disabled={day>=today()} onclick={()=>shift(1)}>›</button></div></div>
 {#if error}<p class="subscriber-note" role="alert">Не удалось загрузить подписчиков. <button class="text-button" onclick={()=>void load()}>Повторить</button></p>{:else if !data}<p class="subscriber-note">{loading?'Загружаем подписчиков…':'Нет замеров за этот период.'}</p>{:else}
 <div class="subscriber-total"><span><strong>{data.total?.toLocaleString('ru-RU')??'—'}</strong><small>подписчиков</small></span><span class:positive={data.change!==null&&data.change>0}>{data.change===null?'':`${data.change>0?'+':''}${data.change} за период`}</span></div>
 {#if points.length}
 <div class="subscriber-plot" bind:clientWidth={width}><svg viewBox={`0 0 ${plotWidth} ${source==='youtube'&&groups.length?340:300}`} role="group" aria-label={`Число подписчиков ${source==='twitch'?'Twitch':'YouTube'}`}>
  {#each [0,.5,1] as fraction}{@const value=Math.round(low+(high-low)*fraction)}<line x1={left} x2={plotWidth-right} y1={y(value)} y2={y(value)} stroke="currentColor" opacity=".12"/><text x="2" y={y(value)+4} fill="currentColor" font-size="11">{value}</text>{/each}
  {#if data.streams.length}<text x="2" y="284" fill="currentColor" font-size="10">Эфиры</text>{/if}
  {#each data.streams as stream}{@const start=x(stream.start)}{@const end=x(stream.end)}<g class="stream-band" role="button" tabindex="0" aria-label={`Эфир ${label(stream.start,true)} ${label(stream.start)}–${label(stream.end)}`} onclick={()=>selectedStream=stream} onkeydown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectedStream=stream;}}}><rect x={start} width={Math.max(2,end-start)} y="278" height="7" fill={color} opacity=".55"/><rect x={Math.max(left,start-8)} width={Math.max(16,end-start)} y="266" height="28" fill="transparent"/><title>{stream.title} · {label(stream.start)}–{label(stream.end)}</title></g>{/each}
  <path d={stepPath(points,x,y)} fill="none" stroke={color} stroke-width="2.5"/>
  {#each (width<450?[0,.5,1]:[0,.25,.5,.75,1]) as fraction}{@const at=window.from+fraction*(window.to-window.from)}<text x={x(at)} y="255" text-anchor={fraction===0?'start':fraction===1?'end':'middle'} fill="currentColor" font-size="11">{days===1?(fraction===1?'24:00':label(at)):label(at,true)}</text>{/each}
  {#each points as point}{#if points.length===1||selectedPoint===point.at}<circle class="count-marker" cx={x(point.at)} cy={y(point.total)} r="4" fill={color}/>{/if}<circle cx={x(point.at)} cy={y(point.total)} r="12" fill="transparent" role="button" tabindex="0" aria-label={`${label(point.at,true)} ${label(point.at)} · ${point.total} подписчиков`} onclick={()=>selectedPoint=point.at} onkeydown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectedPoint=point.at;}}}/>{/each}
  {#if source==='youtube'}<line x1={left} x2={plotWidth-right} y1="316" y2="316" stroke="currentColor" opacity=".18"/>{#each groups as group}{@const item=group.items[0]!}<g class="publication-marker" role="button" tabindex="0" aria-label={`${group.items.length>1?`${group.items.length} публикации`:kind(item)} · ${label(group.at,true)} ${label(group.at)}`} onclick={()=>selectGroup(group.items)} onkeydown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectGroup(group.items);}}}><rect x={x(group.at)-16} y="298" width="32" height="35" fill="transparent"/>{#if group.items.length>1}<circle cx={x(group.at)} cy="316" r="12" fill={color}/><text x={x(group.at)} y="320" text-anchor="middle" fill="#fff" font-size="11">{group.items.length}</text>{:else if item.kind==='video'}<path d={`M${x(group.at)},306 l10,10 -10,10 -10,-10 Z`} fill={color}/>{:else}<circle cx={x(group.at)} cy="316" r="5" fill={item.kind==='unknown'?'none':color} stroke={color} stroke-width="2"/>{/if}</g>{/each}{/if}
 </svg></div>
 {#if selectedStream}<div class="subscriber-selection"><strong>Эфир {label(selectedStream.start,true)} · {label(selectedStream.start)}–{label(selectedStream.end)}</strong><button class="text-button" onclick={()=>{if(selectedStream)onStream(selectedStream.id);}}>Открыть эфир</button></div>{/if}
 {#if currentPoint}{@const point=currentPoint}<div class="subscriber-selection"><strong>{point.total.toLocaleString('ru-RU')} подписчиков</strong><span>{label(point.at,true)} · {label(point.at)}</span>{#if source==='youtube'}<small>Замер счётчика. Точное время подписки неизвестно.</small>{/if}</div>{/if}
 {:else}<p class="subscriber-note">Нет замеров за этот период.</p>{/if}
 {#if source==='youtube'&&groups.length}<div class="subscriber-legend"><span><i class="circle-key"></i>Shorts</span><span><i class="diamond-key"></i>Видео</span></div>{/if}
 {#if source==='youtube'&&data.publications.length}<details class="subscriber-publications" bind:open={publicationsOpen}><summary onclick={()=>selectedGroup=[]}>Публикации за период · {data.publications.length}</summary>{#if selectedGroup.length>1}<p class="subscriber-note">Выбрано публикаций: {selectedGroup.length}. <button class="text-button" onclick={()=>selectedGroup=[]}>Показать все</button></p>{/if}{#each data.publications.filter(item=>selectedGroup.length<2||selectedGroup.includes(item.id)) as item}<div class:selected={selection?.id===item.id} class="publication-row"><button aria-expanded={selection?.id===item.id} onclick={()=>selection=selection?.id===item.id?null:item}><i class:diamond-key={item.kind==='video'} class:circle-key={item.kind!=='video'} class:unknown={item.kind==='unknown'}></i><time>{days===1?label(item.publishedAt):`${label(item.publishedAt,true)} ${label(item.publishedAt)}`}</time><span><small>{kind(item)}</small>{item.title}</span></button>{#if selection?.id===item.id}<a href={`https://www.youtube.com/watch?v=${encodeURIComponent(item.id)}`} target="_blank" rel="noreferrer">Открыть на YouTube ↗</a>{/if}</div>{/each}</details>{/if}

 {/if}
</section>
<style>
 .subscriber-growth{min-width:0;overflow:hidden}.subscriber-growth>header{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 12px;border:0;flex-wrap:wrap}.subscriber-heading{display:flex;align-items:center;gap:6px}.subscriber-heading h2{font-size:16px}.subscriber-switch{display:flex;gap:2px;min-width:0}.subscriber-switch button{flex:1;min-width:0;min-height:44px;border:0;border-radius:6px;background:transparent;color:var(--muted);padding:8px 7px;font-size:12px;white-space:nowrap}.subscriber-switch button.active{background:color-mix(in srgb,var(--subscriber-color) 15%,transparent);color:var(--subscriber-color)}.platform-switch{flex:0 0 auto}.subscriber-controls{display:flex;align-items:center;justify-content:space-between;gap:4px 8px;padding:0 12px;flex-wrap:wrap}.period-switch{flex:1 0 132px;max-width:230px}.subscriber-date{display:flex;align-items:center;gap:0;flex:0 1 auto}.subscriber-date>button{width:44px;min-width:44px;height:44px;min-height:44px;font-size:22px;padding:0;border:0;background:transparent}.subscriber-date label{position:relative;display:grid;place-items:center;min-height:44px;font-size:12px;white-space:nowrap;color:var(--muted)}.subscriber-date input{position:absolute;inset:0;width:100%;height:100%;opacity:0;min-width:0;padding:0;cursor:pointer}.subscriber-date label:focus-within{outline:2px solid var(--accent);outline-offset:-3px;border-radius:6px}.subscriber-total{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:4px 12px;font-size:13px;color:var(--muted)}.subscriber-total>span:first-child{display:flex;align-items:baseline;gap:8px}.subscriber-total strong{font-size:28px;color:var(--text)}.subscriber-total small{font-size:12px}.positive{color:var(--teal)}.subscriber-plot{padding:0 8px;min-width:0}.subscriber-plot svg{width:100%;height:auto;display:block;color:var(--muted)}.subscriber-plot [role=button]{cursor:pointer}.subscriber-plot [role=button]:focus{outline:2px solid var(--subscriber-color)}.subscriber-note{padding:10px 12px;margin:0;color:var(--muted);font-size:12px;line-height:1.5}.subscriber-legend{display:flex;flex-wrap:wrap;gap:12px;padding:0 12px 8px;font-size:11px;color:var(--muted)}.subscriber-legend span{display:flex;align-items:center;gap:6px}.circle-key,.diamond-key{display:inline-block;flex-shrink:0;background:var(--subscriber-color)}.circle-key{width:9px;height:9px;border-radius:50%}.diamond-key{width:13px;height:13px;transform:rotate(45deg)}.unknown{background:transparent;border:1px solid var(--subscriber-color)}.subscriber-publications{margin:0 12px;border-top:1px solid var(--border)}.subscriber-publications summary{padding:8px 0;cursor:pointer;font-size:13px}.publication-row{border-top:1px solid var(--border);padding:0 4px}.publication-row.selected{background:var(--bg);border-radius:6px}.publication-row>button{display:grid;grid-template-columns:16px auto minmax(0,1fr);gap:8px;align-items:center;width:100%;border:0;background:transparent;text-align:left;padding:8px 0;color:var(--text);font-size:12px;min-height:44px}.publication-row time{color:var(--muted);font-size:11px}.publication-row span{min-width:0;overflow-wrap:anywhere}.publication-row small{display:block;color:var(--muted);font-size:11px;margin-bottom:2px}.publication-row a{display:block;text-align:right;font-size:12px;padding:8px 0;color:var(--subscriber-color)}.subscriber-selection{display:flex;flex-wrap:wrap;gap:8px;margin:4px 12px;padding:8px;background:var(--bg);border-radius:6px;font-size:12px}.subscriber-selection small{flex-basis:100%;color:var(--muted)}
 @media(max-width:359px){.subscriber-controls{gap:0}.period-switch{flex-basis:100%;max-width:none}.subscriber-date{margin-left:auto}.subscriber-heading h2{font-size:15px}}
</style>
